/* From Uiverse.io by TheAbieza - Tags: flat design, loading, loader, vscode, floating, box-shadow */
.__UIV_SCOPE__ .container {
  width: fit-content;
  gap: 10px
}

.__UIV_SCOPE__ .folder {
  width: min-content;
  margin: auto;
  animation: float 2s infinite linear;
}

.__UIV_SCOPE__ .folder .top {
  background-color: #FF8F56;
  width: 60px;
  height: 12px;
  border-top-right-radius: 10px;
}

.__UIV_SCOPE__ .folder .bottom {
  background-color: #FFCE63;
  width: 100px;
  height: 70px;
  box-shadow: 5px 5px 0 0 #283149;
  border-top-right-radius: 8px;
}

.__UIV_SCOPE__ .container .title {
  font-size: .9em;
  color: #283149;
  text-align: center;
  margin-top: 15px;
}

@keyframes float {
  0% {
    transform: translatey(0px);
  }

  50% {
    transform: translatey(-25px);
  }

  100% {
    transform: translatey(0px);
  }
}
